        try {
          const style = window.getComputedStyle(node);
          visible = style.display !== 'none' && style.visibility !== 'hidden' && node.getClientRects().length > 0;
        } catch (_) {}
        return { node, text, visible, score: (visible ? 1000000 : 0) + index };
