    grok: 'Grok',
    lechat: 'Le Chat',
    mistral: 'Le Chat',
    qwen: 'Qwen',
    deepseek: 'DeepSeek',
    perplexity: 'Perplexity',
    'z.ai': 'Z.ai',
    zai: 'Z.ai',
    kimi: 'Kimi',
